-- Professional multi-source updater
CREATE TABLE IF NOT EXISTS `update_sources` (`id` TINYINT UNSIGNED PRIMARY KEY,`github_repo` VARCHAR(191) NULL,`asset_pattern` VARCHAR(191) NOT NULL DEFAULT 'RedFox*.zip',`allow_unsigned_local` TINYINT(1) NOT NULL DEFAULT 0,`auto_check` TINYINT(1) NOT NULL DEFAULT 1,`last_check_at` BIGINT UNSIGNED NULL,`last_version` VARCHAR(100) NULL,`last_url` VARCHAR(1000) NULL,`last_error` VARCHAR(1000) NULL,`updated_at` BIGINT UNSIGNED NOT NULL DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
INSERT IGNORE INTO `update_sources` (`id`) VALUES (1);
CREATE TABLE IF NOT EXISTS `update_jobs` (`id` BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,`job_id` CHAR(32) NOT NULL,`version` VARCHAR(100) NOT NULL,`source` VARCHAR(30) NOT NULL,`signed_package` TINYINT(1) NOT NULL DEFAULT 0,`status` VARCHAR(30) NOT NULL,`total_files` INT UNSIGNED NOT NULL DEFAULT 0,`changed_files` INT UNSIGNED NOT NULL DEFAULT 0,`added_files` INT UNSIGNED NOT NULL DEFAULT 0,`skipped_files` INT UNSIGNED NOT NULL DEFAULT 0,`file_backup_path` VARCHAR(1000) NULL,`database_backup_path` VARCHAR(1000) NULL,`error_message` VARCHAR(2000) NULL,`actor` VARCHAR(191) NULL,`created_at` BIGINT UNSIGNED NOT NULL,`started_at` BIGINT UNSIGNED NULL,`finished_at` BIGINT UNSIGNED NULL,UNIQUE KEY `uq_uj_job` (`job_id`),KEY `idx_uj_status_time` (`status`,`created_at`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
